    public function __construct(private \mysqli $db,private string $legacyPrefix,private string $prefix,private ObjectCardReader $previous) {}
    public function read(int $id):?array
    {
        $s=$this->db->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');
        $s->execute([$this->prefix.'fm2_assignment_order_applications']);$exists=$s->get_result()->fetch_row()!==null;$s->close();
        if(!$exists)return $this->withActorNames($this->previous->read($id));
        $lookup=C\AssignmentOrderApplicationReaderFactory::create($this->db,$this->prefix)->readCurrent($id);
        if($lookup->status==='not_found'){ $card=$this->previous->read($id);if($card!==null){$q=$this->db->prepare('SELECT 1 FROM `'.$this->prefix.'fm2_pilot_object_details` WHERE object_id=? AND content_sha256=SHA2(payload_json,256)');$q->execute([$id]);if($q->get_result()->fetch_row()!==null)$card['dataOrigin']='migration_native';$q->close();}$card=$this->withConfirmedOriginal($id,$card);return $this->withActorNames($card);}
        if($lookup->status!=='found'||$lookup->value===null)throw new PilotHttpInfrastructureUnavailable();
        $v=$lookup->value;$a=$v['application'];
        $object=(new \FMonitor2\InstallationProcess\MariaDbLegacyInstallationObject($this->db,$this->legacyPrefix))->getInstallationObjectSnapshot($id);
        $s=$this->db->prepare('SELECT process_state,actual_start_date,opened_at,opened_by_user_id FROM `'.$this->prefix.'fm2_installation_cases` WHERE id=?');
        $s->execute([$a['caseId']]);$case=$s->get_result()->fetch_assoc();$s->close();if($case===null)throw new PilotHttpInfrastructureUnavailable();
        $opened=$case['actual_start_date']!==null&&$case['opened_at']!==null&&$case['opened_by_user_id']!==null;
        $installers=\array_map(static fn($person)=>$person+['status'=>'employed'],$v['selectedInstallers']);
        $revision=$this->db->prepare('SELECT v.byte_size,v.revision_number,v.uploaded_at_utc FROM `'.$this->prefix.'fm2_assignment_order_original_revisions` v JOIN `'.$this->prefix.'fm2_assignment_order_original_roots` r ON r.root_original_id=v.root_original_id WHERE v.revision_id=? AND r.assignment_order_id=? LIMIT 2');$revision->execute([$a['originalRevisionId'],$a['orderId']]);$original=$revision->get_result()->fetch_all(MYSQLI_ASSOC);$revision->close();if(\count($original)!==1)throw new PilotHttpInfrastructureUnavailable();$artifacts=[['type'=>'signed_original','filename'=>'Подписанный оригинал.pdf','mediaType'=>'application/pdf','size'=>(int)$original[0]['byte_size'],'revisionNumber'=>(int)$original[0]['revision_number'],'uploadedAt'=>\str_replace(' ','T',$original[0]['uploaded_at_utc']).'Z','href'=>'/pilot/objects/'.$id.'/assignment-orders/'.$a['orderId'].'/originals/'.$a['originalRevisionId'].'/download']];
        $card=['id'=>$id,'address'=>$object['address'],'entrance'=>$object['entrance'],'registrationNumber'=>$object['objectRegistrationNumber'],
            'plannedStartDate'=>$object['plannedStartDate'],'plannedFinishDate'=>$object['plannedFinishDate'],
            'status'=>$case['process_state']==='needs_assignment_change'?'Требуется изменение':($opened?'Монтажные работы':'Готов к открытию'),'applicationId'=>$a['applicationId'],'confirmedOriginal'=>['orderId'=>$a['orderId'],'revisionId'=>$a['originalRevisionId'],'sequence'=>$a['sequence']],
