            'openedByUserId'=>$opened?(int)$case['opened_by_user_id']:null,'actualStartDateUnknownAtCutover'=>false,'activeCaseProvenance'=>null,'dataOrigin'=>'native',
            'events'=>[['type'=>'Состав применён','occurredAt'=>$a['appliedAt'],'actorId'=>$a['appliedBy']]],'hasPtoAct'=>$object['ptoActDate']!==null];if(!$opened)$card=$this->withConfirmedOriginal($id,$card,(int)$a['sequence']);return$this->withActorNames($card);
    }

    private function withConfirmedOriginal(int $objectId,?array $card,int $sequence=0):?array
    {
        if($card===null||$card['opened'])return$card;$sql='SELECT s.assignment_order_id,s.order_version,s.composition_identity,s.composition_sha256,s.control_engineer_user_id,s.control_engineer_fio_snapshot,s.control_engineer_position_snapshot,s.selected_at_utc,r.current_revision_id,v.revision_number,v.document_date,v.uploaded_at_utc,v.actor_user_id,v.byte_size FROM `'.$this->prefix.'fm2_installation_cases` c JOIN `'.$this->prefix.'fm2_assignment_order_selections` s ON s.installation_case_id=c.id AND s.selection_revision=(SELECT MAX(latest.selection_revision) FROM `'.$this->prefix.'fm2_assignment_order_selections` latest WHERE latest.installation_case_id=c.id) JOIN `'.$this->prefix.'fm2_assignment_order_original_roots` r ON r.installation_case_id=c.id AND r.assignment_order_id=s.assignment_order_id AND r.composition_identity=s.composition_identity AND r.composition_sha256=s.composition_sha256 JOIN `'.$this->prefix.'fm2_assignment_order_original_revisions` v ON v.root_original_id=r.root_original_id AND v.revision_id=r.current_revision_id WHERE c.legacy_installation_object_id=? AND c.actual_start_date IS NULL AND c.opened_at IS NULL AND c.opened_by_user_id IS NULL LIMIT 2';$q=$this->db->prepare($sql);$q->execute([$objectId]);$rows=$q->get_result()->fetch_all(MYSQLI_ASSOC);$q->close();if($rows===[]){$card['status']='Требуется распоряжение';$card['order']=null;$card['controlEngineer']=null;unset($card['confirmedOriginal']);return$card;}if(\count($rows)!==1)throw new PilotHttpInfrastructureUnavailable();$row=$rows[0];$orderId=(int)$row['assignment_order_id'];$members=$this->db->prepare('SELECT installer_tab_id,fio_snapshot,position_snapshot FROM `'.$this->prefix.'fm2_assignment_order_selection_members` WHERE assignment_order_id=? ORDER BY installer_tab_id');$members->execute([$orderId]);$installers=\array_map(static fn(array$x):array=>['tabId'=>(int)$x['installer_tab_id'],'fullName'=>(string)$x['fio_snapshot'],'position'=>(string)$x['position_snapshot'],'status'=>'employed'],$members->get_result()->fetch_all(MYSQLI_ASSOC));$members->close();if($orderId<1||$installers===[]||!\is_string($row['current_revision_id'])||$row['current_revision_id']==='')throw new PilotHttpInfrastructureUnavailable();$engineer=['userId'=>(int)$row['control_engineer_user_id'],'fullName'=>(string)$row['control_engineer_fio_snapshot'],'position'=>(string)$row['control_engineer_position_snapshot']];$revision=(string)$row['current_revision_id'];$uploaded=\str_replace(' ','T',(string)$row['uploaded_at_utc']).'Z';$artifact=['type'=>'signed_original','filename'=>'Подписанный оригинал.pdf','mediaType'=>'application/pdf','size'=>(int)$row['byte_size'],'revisionNumber'=>(int)$row['revision_number'],'uploadedAt'=>$uploaded,'href'=>'/pilot/objects/'.$objectId.'/assignment-orders/'.$orderId.'/originals/'.$revision.'/download'];$card['status']='Готов к открытию';$card['applicationId']??=null;$card['confirmedOriginal']=['orderId'=>$orderId,'revisionId'=>$revision,'sequence'=>$sequence];$card['order']=['version'=>(int)$row['order_version'],'status'=>'confirmed','orderDate'=>(string)$row['document_date'],'preparedAt'=>(string)$row['selected_at_utc'],'registrationNumber'=>null,'artifacts'=>[$artifact],'organizationType'=>\count($installers)===1?'individual':'brigade','engineer'=>$engineer,'installers'=>$installers];$card['controlEngineer']=$engineer;\array_unshift($card['events'],['type'=>'assignment_order_signed_original_uploaded','occurredAt'=>$uploaded,'actorId'=>(int)$row['actor_user_id']]);return$card;
    }

    private function withActorNames(?array $card):?array
    {
        if($card===null)return null;$events=$card['events']??[];$ids=[];foreach($events as$event){$id=(int)($event['actorId']??0);if($id>0)$ids[$id]=$id;}
        $names=[];if($ids!==[]){$table=$this->prefix.'fm2_pilot_users';$exists=$this->db->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$exists->execute([$table]);$available=$exists->get_result()->fetch_row()!==null;$exists->close();if($available){$placeholders=\implode(',',\array_fill(0,\count($ids),'?'));$users=$this->db->prepare('SELECT user_id,full_name,email FROM `'.$table.'` WHERE user_id IN ('.$placeholders.')');$users->execute(\array_values($ids));foreach($users->get_result()->fetch_all(MYSQLI_ASSOC)as$user){$name=\trim((string)$user['full_name']);if($name==='')$name=\trim((string)$user['email']);$names[(int)$user['user_id']]=$name!==''?$name:null;}$users->close();}}
        foreach($events as&$event){$actor=(int)($event['actorId']??0);$event['actorName']=$names[$actor]??null;}unset($event);$card['events']=$events;return$card;
    }
}
